INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-16-z0-q0','nism-16-z0','The spot price of a commodity is ₹6410 and the near-month futures price is ₹6425. The basis (spot − futures) is:','["₹15","-₹15","₹6,410","₹6,425"]',1,'Basis = spot − futures; a negative value indicates contango.',0) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
